  // ✅ NEW: Detect "more options" requests
  detectMoreOptionsRequest(userMessage) {
    const messageLower = userMessage.toLowerCase();
    
    // Enhanced patterns for "more options" requests
    const moreOptionsPatterns = [
      // Direct requests
      /(?:show me|give me|find me|get me)\s+(?:more|additional|other|different)\s+(?:options|vehicles|cars|choices)/i,
      /(?:more|additional|other|different)\s+(?:options|vehicles|cars|choices)/i,
      
      // Rejection + request patterns
      /(?:not interested|don't like|not for me|pass|skip).*(?:show me|give me|more|other)/i,
      /(?:no|nope|nah).*(?:show me|give me|more|other|different)/i,
      
      // Alternative requests
      /(?:something else|anything else|different|other|alternatives)/i,
      
      // Specific patterns from user conversation
      /(?:not right now|not interested|show me more|more options)/i
    ];
    
    // Check for rejection patterns
    const rejectionPatterns = [
      /^(?:no|nope|nah|not interested|not right now|not for me|pass|skip)$/i,
      /(?:not interested|don't like|not for me|not right|not what)/i,
      /(?:too expensive|too cheap|too big|too small|not my style)/i
    ];
    
    const isMoreOptionsRequest = moreOptionsPatterns.some(pattern => pattern.test(messageLower));
    const isRejection = rejectionPatterns.some(pattern => pattern.test(messageLower));
    
    console.log('🔍 More options detection:', {
      message: userMessage,
      isMoreOptionsRequest,
      isRejection,
      detectedPattern: moreOptionsPatterns.find(pattern => pattern.test(messageLower))
    });
    
    return isMoreOptionsRequest || isRejection;
  }


