  createFinanceTools() {
    return [
      {
        name: "calculate_payment",
        description: "Calculate monthly payment options with real calculations",
        func: async (vehiclePrice, downPayment, term, apr = 7.9) => {
          const principal = vehiclePrice - (downPayment || 0);
          const monthlyRate = apr / 100 / 12;
          const numPayments = term * 12;
          
          if (monthlyRate === 0) {
            return { monthlyPayment: principal / numPayments, options: "Interest-free financing" };
          }
          
          const monthlyPayment = principal * (monthlyRate * Math.pow(1 + monthlyRate, numPayments)) / 
                                (Math.pow(1 + monthlyRate, numPayments) - 1);
          
          return { 
            monthlyPayment: Math.round(monthlyPayment),
            totalCost: Math.round(monthlyPayment * numPayments + (downPayment || 0)),
            apr: apr,
            term: term
          };
        }
      },
      {
        name: "calculate_lease",
        description: "Calculate lease payment options",
        func: async (vehiclePrice, downPayment, term, milesPerYear = 12000) => {
          // Simplified lease calculation (would need actual residual values in production)
          const residualValue = vehiclePrice * 0.55; // 55% residual for 36 months
          const depreciation = vehiclePrice - residualValue;
          const monthlyDepreciation = depreciation / term;
          const moneyFactor = 0.0025; // Equivalent to 6% APR
          const monthlyFinance = (vehiclePrice + residualValue) * moneyFactor;
          const monthlyPayment = monthlyDepreciation + monthlyFinance;
          
          return {
            monthlyPayment: Math.round(monthlyPayment),
            totalCost: Math.round(monthlyPayment * term + (downPayment || 0)),
            term: term,
            milesPerYear: milesPerYear
          };
        }
      },
      {
        name: "get_insurance_quotes",
        description: "Get insurance quotes for the vehicle",
        func: async (vehicleInfo, customerInfo) => {
          return { quotes: "Insurance options available" };
        }
      }
    ];
  }

