  // Inventory-related methods for inventory specialist
  async findAlternativeVehicles(preferences) {
    try {
      console.log('🔍 Finding alternative vehicles based on preferences:', preferences);
      
      // Get current inventory
      const inventory = await this.getDealerInventory(this.currentDealerId);
      if (!inventory || inventory.length === 0) {
        return { alternatives: [], message: 'No vehicles currently available' };
      }
      
      // Filter based on preferences
      let alternatives = inventory.filter(vehicle => {
        let match = true;
        
        if (preferences.make && vehicle.make !== preferences.make) match = false;
        if (preferences.model && vehicle.model !== preferences.model) match = false;
        if (preferences.price_range && vehicle.price > preferences.price_range) match = false;
        if (preferences.features && preferences.features.length > 0) {
          const vehicleFeatures = vehicle.features || [];
          const hasAllFeatures = preferences.features.every(feature => 
            vehicleFeatures.some(vf => vf.toLowerCase().includes(feature.toLowerCase()))
          );
          if (!hasAllFeatures) match = false;
        }
        
        return match;
      });
      
      // Sort by relevance (price, then features match)
      alternatives.sort((a, b) => {
        if (a.price !== b.price) return a.price - b.price;
        return (b.features?.length || 0) - (a.features?.length || 0);
      });
      
      return {
        alternatives: alternatives.slice(0, 5), // Return top 5 alternatives
        message: `Found ${alternatives.length} alternative vehicles matching your preferences`
      };
    } catch (error) {
      console.error('Error finding alternative vehicles:', error);
      return { alternatives: [], message: 'Unable to find alternatives at this time' };
    }
  }

  async checkVehicleAvailability(vehicleId) {
    try {
      console.log('🔍 Checking availability for vehicle:', vehicleId);
      
      const vehicle = await this.getVehicleContext(vehicleId);
      if (!vehicle) {
        return { available: false, message: 'Vehicle not found' };
      }
      
      const status = vehicle.status || 'unknown';
      const available = ['available', 'in_stock', 'ready'].includes(status.toLowerCase());
      
      return {
        available,
        status,
        message: available ? 'Vehicle is available' : `Vehicle status: ${status}`,
        vehicle: vehicle
      };
    } catch (error) {
      console.error('Error checking vehicle availability:', error);
      return { available: false, message: 'Unable to check availability' };
    }
  }

