        // .replace(/dollars/g, '')       // Remove "dollars"
        // .replace(/k|000/g, '000')      // Convert k/000 to 000
        // .replace(/[^\d]/g, '');        // Keep only digits
      
      console.log(`🔍 parsePrice cleaned: "${cleanText}"`);
      
      const price = parseInt(cleanText);
      const result = isNaN(price) ? 0 : price;
      
      console.log(`🔍 parsePrice result: ${result}`);
