  /**
   * Determine if agent should discuss finance
   */
  shouldDiscussFinance(section, slots) {
    return section === 'finance' && 
           slots.vehicle?.inventory_choice &&
           !slots.finance?.preferred_method;
  }
  
  /**
   * Determine if agent should appraise trade-in
   */
  shouldAppraiseTrade(section, slots) {
    return section === 'trade_in' && 
           slots.trade_in?.vehicle_info?.make &&
           !slots.trade_in?.estimated_value;
  }
  
  // Check if all mandatory slots are filled
  // ✅ REMOVED: Old duplicate areMandatorySlotsFilled method - using consolidated version above

