/**
 * ✅ NEW: Generate mock conversational response
 */
DAIVEService.prototype.generateMockConversationalResponse = function(userMessage, currentStep) {
  const conversationalResponses = {
    inquiry: [
      "That's wonderful to hear! Toyota SUVs are fantastic choices for families. The RAV4 and Highlander are particularly popular. What draws you to Toyota specifically?",
      "I love that enthusiasm! Toyota has built a great reputation for reliability. Are you looking for something compact like the RAV4 or do you need more space?"
    ],
    vehicle_selection: [
      "That's so great to hear! Your friend has excellent taste - the RAV4 is one of our most popular models for good reason. It sounds like you're already familiar with how reliable and practical it is.",
      "I love hearing that! There's nothing better than a personal recommendation from someone you trust. What does your friend like most about their RAV4?"
    ],
    qualification: [
      "I can hear the excitement in your message! That rate really is competitive, and with your excellent credit, you definitely earned it. This is such an exciting step!",
      "Your enthusiasm is contagious! It's always rewarding when we can offer our customers great terms. You've made some excellent choices throughout this process."
    ]
  };
  
  const responses = conversationalResponses[currentStep] || [
    "Thank you for sharing that! I'm here to help make this process as smooth as possible for you.",
    "I appreciate your enthusiasm! Let me know if you have any questions along the way."
  ];
  
  return responses[Math.floor(Math.random() * responses.length)];
};

