  // ✅ NEW: Check if vehicle is already selected (for persistence across steps)
  hasSelectedVehicle(conversationContext) {
    const step3 = conversationContext.Daivesteps?.[3];
    if (!step3) return false;
    
    // Check multiple possible locations for selected vehicle
    const selectedVehicle = 
      step3.slots?.inventory_choice ||
      step3.slots?.VehicleSelection?.selectedVehicle ||
      step3.selectedVehicle;
    
    // ✅ FIX: Also check selectedVehicles array
    const selectedVehicles = step3.slots?.selectedVehicles || [];
    if (dollarMatch) {
      const amounts = dollarMatch.map(match => {
        const cleanAmount = parseInt(match.replace(/[$,]/g, ''));
        return cleanAmount;
      }).filter(amount => amount > 1000); // Reasonable vehicle amounts
      
      if (amounts.length > 0) {
        return { newBudget: Math.max(...amounts) };
      }
    }
    
    // Look for "increase" or "more" with numbers
    const increaseMatch = messageLower.match(/(increase|more|up|raise).*\b([0-9,]+)\b/);
    if (increaseMatch) {
      const amount = parseInt(increaseMatch[2].replace(/,/g, ''));
      if (amount > 1000) {
        return { newBudget: amount };
      }
    }
    
    // Look for percentage increases like "20% more" or "1.2x"
    const percentMatch = messageLower.match(/\b([0-9]+)%\s*(more|increase|higher)/);
    if (percentMatch) {
      const currentBudget = conversationContext.Daivesteps?.[2]?.slots?.budget?.max_price || 
                           conversationContext.Daivesteps?.[2]?.slots?.budget?.target_price;
      if (currentBudget) {
        const percentage = parseInt(percentMatch[1]) / 100;
        return { newBudget: Math.round(currentBudget * (1 + percentage)) };
      }
    }
    
    return { newBudget: null };
  }
  
  detectVehicleConditionChange(userMessage) {
    const messageLower = userMessage.toLowerCase();
    
    // Detect explicit condition changes
    if (messageLower.includes('new') && !messageLower.includes('pre-owned')) {
      return { newCondition: 'new' };
    } else if (messageLower.includes('pre-owned') || messageLower.includes('used') || messageLower.includes('second')) {
      return { newCondition: 'pre-owned' };
    }
    
    return { newCondition: null };
  }
  
  detectMakeChange(userMessage) {
    const messageLower = userMessage.toLowerCase();
    
    // Common vehicle makes to detect
    const makes = ['toyota', 'honda', 'hyundai', 'ford', 'chevrolet', 'kia', 'nissan', 'mazda', 'subaru', 'volkswagen'];
    
    for (const make of makes) {
      if (messageLower.includes(make)) {
        return { newMake: make };
      }
    }
    
    return { newMake: null };
  }
  
  detectVehicleTypeChange(userMessage) {
    const messageLower = userMessage.toLowerCase();
    
    // Detect vehicle types
    if (messageLower.includes('suv') || messageLower.includes('s.u.v') || messageLower.includes('sport utility')) {
      return { newType: 'SUV' };
    } else if (messageLower.includes('sedan') || messageLower.includes('car')) {
      return { newType: 'sedan' };
    } else if (messageLower.includes('truck') || messageLower.includes('pickup')) {
      return { newType: 'truck' };
    } else if (messageLower.includes('crossover') || messageLower.includes('compact')) {
      return { newType: 'crossover' };
    }
    
    return { newType: null };
  }
  
  detectColorToneChange(userMessage) {
    const messageLower = userMessage.toLowerCase();
    
    if (messageLower.includes('light') && !messageLower.includes('dark')) {
      return { newColorTone: 'light' };
    } else if (messageLower.includes('dark') && !messageLower.includes('light')) {
      return { newColorTone: 'dark' };
    }
    
    return { newColorTone: null };
  }

