  // ✅ NEW: Store selected vehicle in conversation context
  storeSelectedVehicle(conversationContext, vehicle) {
    if (!conversationContext.Daivesteps[3]) {
      conversationContext.Daivesteps[3] = { slots: {} };
    }
    
    if (!conversationContext.Daivesteps[3].slots) {
      conversationContext.Daivesteps[3].slots = {};
    }
    
    if (!conversationContext.Daivesteps[3].slots.selectedVehicles) {
      conversationContext.Daivesteps[3].slots.selectedVehicles = [];
    }
    
    // Add vehicle to selectedVehicles array
    conversationContext.Daivesteps[3].slots.selectedVehicles.push(vehicle);
    
    // Also store in VehicleSelection for compatibility
    if (!conversationContext.Daivesteps[3].slots.VehicleSelection) {
      conversationContext.Daivesteps[3].slots.VehicleSelection = {};
    }
    
    conversationContext.Daivesteps[3].slots.VehicleSelection.selectedVehicle = vehicle;
    conversationContext.Daivesteps[3].slots.VehicleSelection.hasSelectedVehicle = true;
    
    // ✅ CRITICAL: Update mandatory slots in Step 1 when vehicle is selected
    if (!conversationContext.Daivesteps[1]) {
      conversationContext.Daivesteps[1] = {};
    }
    
    // Update make and model in Step 1 (mandatory slots)
    conversationContext.Daivesteps[1].make = vehicle.make;
    conversationContext.Daivesteps[1].model = vehicle.model;
    
    // ✅ AUTO-COMPLETE COLOR TONE: Extract color from selected vehicle and set automatically
    let colorTone = null;
    if (vehicle.colors && vehicle.colors.length > 0) {
      // Use the first available color
      const primaryColor = vehicle.colors[0].toLowerCase();
      if (primaryColor.includes('white') || primaryColor.includes('silver') || primaryColor.includes('beige') || primaryColor.includes('pearl')) {
        colorTone = 'light';
      } else if (primaryColor.includes('black') || primaryColor.includes('navy') || primaryColor.includes('dark') || primaryColor.includes('gray') || primaryColor.includes('grey')) {
        colorTone = 'dark';
      } else {
        // For other colors, determine based on brightness
        colorTone = primaryColor.includes('red') || primaryColor.includes('blue') || primaryColor.includes('green') ? 'dark' : 'light';
      }
    } else if (vehicle.color) {
      // Use single color field if colors array is not available
      const primaryColor = vehicle.color.toLowerCase();
      if (primaryColor.includes('white') || primaryColor.includes('silver') || primaryColor.includes('beige') || primaryColor.includes('pearl')) {
        colorTone = 'light';
      } else if (primaryColor.includes('black') || primaryColor.includes('navy') || primaryColor.includes('dark') || primaryColor.includes('gray') || primaryColor.includes('grey')) {
        colorTone = 'dark';
      } else {
        colorTone = primaryColor.includes('red') || primaryColor.includes('blue') || primaryColor.includes('green') ? 'dark' : 'light';
      }
    } else {
      // Default to 'light' if no color information is available
      colorTone = 'light';
    }
    
    // Set the automatically determined color tone
    conversationContext.Daivesteps[1].color_tone = colorTone;
    
    console.log(`✅ Vehicle stored: ${vehicle.year} ${vehicle.make} ${vehicle.model}`);
    console.log('✅ Mandatory slots updated in Step 1:', {
      make: vehicle.make,
      model: vehicle.model,
      color_tone: colorTone
    });
  }

