  async handleInquiryStepOptimized(userMessage, intentResult, conversationContext, slots) {
    console.log('📞 Handling Inquiry Step (Optimized)');
    
    // Use existing SlotManager for mandatory slot checking
    const slotStatus = this.getMandatorySlotsStatusOptimized(conversationContext);
    
    if (!slotStatus.filled && slotStatus.nextEmpty) {
      console.log(`🔍 Missing slots in inquiry: ${slotStatus.missing.join(', ')}`);
      return await this.generateSlotCollectionResponseOptimized(slotStatus.nextEmpty, conversationContext);
    }
    
    // ✅ NEW: Check for vehicle selection when all mandatory slots are filled
    if (slotStatus.filled) {
      console.log('✅ All mandatory slots filled - checking for vehicle selection...');
      
      // Detect vehicle selection from user message
      const vehicleSelection = this.detectVehicleSelection(userMessage, null, conversationContext);
      
      if (vehicleSelection && vehicleSelection.selected) {
        console.log('🎯 Vehicle selection detected - progressing to vehicle_selection step');
        
        // Store selected vehicle
        if (!conversationContext.Daivesteps[3]) {
          conversationContext.Daivesteps[3] = { slots: {} };
        }
        conversationContext.Daivesteps[3].slots.selectedVehicles = [vehicleSelection.vehicle];
        
        // Mark inquiry step as completed
        if (!conversationContext.Daivesteps[1]) {
          conversationContext.Daivesteps[1] = { slots: {} };
        }
        conversationContext.Daivesteps[1].status = 'completed';
        conversationContext.Daivesteps[1].completedAt = new Date().toISOString();
        
        // Progress to vehicle selection step
        conversationContext.currentJourneyStep = 'vehicle_selection';
        
        return {
          response: `Perfect! I can see you're interested in the ${vehicleSelection.vehicle.year} ${vehicleSelection.vehicle.make} ${vehicleSelection.vehicle.model}. Let me show you the available options and we can arrange a test drive.`,
          agentType: 'Sales Consultant',
          conversationContext
        };
      }
    }
    
    // Handle intent-specific responses
    switch (intentResult.intent) {
      case 'general_inquiry':
      case 'greeting':
        return { response: "Hello! Welcome to our dealership. How can I assist you with finding your perfect vehicle today?", agentType: 'Sales Consultant', conversationContext };
      
      case 'vehicle_inquiry':
        return { response: "I'd be happy to help you find the right vehicle. What type of vehicle interests you most?", agentType: 'Sales Consultant', conversationContext };
      
      case 'budget_inquiry':
        return { response: "What's your budget range for the vehicle you're looking for?", agentType: 'Sales Consultant', conversationContext };
      
      default:
        return { response: "I'm here to help you find the perfect vehicle. What can I assist you with today?", agentType: 'Sales Consultant', conversationContext };
    }
  }

  async handleLeadCaptureStep(userMessage, intentResult, conversationContext, slots) {
    console.log('📝 Handling Lead Capture Step');
    
    const mandatorySlots = this.getMandatorySlotsForStepOptimized('lead_capture');
    const missingSlots = this.getMissingMandatorySlotsOptimized(conversationContext, mandatorySlots);
    
    if (missingSlots.length > 0) {
      return this.generateSlotCollectionResponseOptimized(missingSlots[0], conversationContext);
    }
    
    return { response: "Fantastic! We have your preferences. Shall I share available inventory options?", agentType: 'Sales Consultant', conversationContext };
  }

