        if (!inventoryData || inventoryData.length === 0 || isGeneralVehicleRequest) {
          // 🚫 DISABLED: generateConversationalResponse bypasses mandatory slot enforcement
          console.log('🚫 generateConversationalResponse DISABLED - using slot-based flow instead');
          return null; // Let other methods handle this
      }
      
