  /**
   * Request handoff for a conversation
   */
  async requestHandoff(conversationId, reason = 'Customer requested human assistance') {
    try {
      console.log('🔄 Requesting handoff for conversation:', conversationId, 'reason:', reason);
      
      const { pool } = await import('../database/connection.js');
      
      const updateQuery = `
        UPDATE daive_conversations 
        SET 
          handoff_requested = true,
          handoff_reason = $1,
          handoff_requested_at = NOW(),
          updated_at = NOW()
        WHERE id = $2
      `;
      
      await pool.query(updateQuery, [reason, conversationId]);
      console.log('✅ Handoff requested successfully for conversation:', conversationId);
      
      return { success: true, message: 'Handoff requested successfully' };
      
    } catch (error) {
      console.error('❌ Error requesting handoff:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Accept handoff for a conversation
   */
  async acceptHandoff(conversationId, userId) {
    try {
      console.log('✅ Accepting handoff for conversation:', conversationId, 'by user:', userId);
      
      const { pool } = await import('../database/connection.js');
      
      const updateQuery = `
        UPDATE daive_conversations 
        SET 
          handoff_requested = false,
          handoff_accepted_at = NOW(),
          handoff_accepted_by = $1,
          updated_at = NOW()
        WHERE id = $2
      `;
      
      await pool.query(updateQuery, [userId, conversationId]);
      console.log('✅ Handoff accepted successfully for conversation:', conversationId);
      
      return { success: true, message: 'Handoff accepted successfully' };
      
    } catch (error) {
      console.error('❌ Error accepting handoff:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get conversations for leads management
   */
  async getConversations(dealerId, page = 1, limit = 20, status = null, handoffStatus = null) {
    try {
      console.log('📋 Getting conversations for dealer:', dealerId, 'page:', page, 'status:', status, 'handoffStatus:', handoffStatus);
      
      const { pool } = await import('../database/connection.js');
      
      let query = `
        SELECT 
          dc.*, 
          v.make, v.model, v.year, v.vin, v.price,
          c.first_name, c.last_name, c.email as customer_email_from_table, c.phone as customer_phone_from_table
        FROM daive_conversations dc
        LEFT JOIN vehicles v ON dc.vehicle_id = v.id
        LEFT JOIN customers c ON dc.customer_id = c.id
        WHERE dc.dealer_id = $1
      `;
      
      const params = [dealerId];
      let paramIndex = 2;

      if (status && status !== 'all') {
        query += ` AND dc.lead_status = $${paramIndex}`;
        params.push(status);
        paramIndex++;
      }

      if (handoffStatus && handoffStatus !== 'all') {
        if (handoffStatus === 'requested') {
          query += ` AND dc.handoff_requested = true`;
        } else if (handoffStatus === 'pending') {
          query += ` AND dc.handoff_requested = true`;
        } else if (handoffStatus === 'accepted') {
          query += ` AND dc.handoff_requested = false`;
        }
      }

      query += ` ORDER BY dc.created_at DESC LIMIT $${paramIndex} OFFSET $${paramIndex + 1}`;
      params.push(parseInt(limit), (parseInt(page) - 1) * parseInt(limit));

      const result = await pool.query(query, params);
      
      // Get total count
      let countQuery = `
        SELECT COUNT(*) as total
        FROM daive_conversations dc
        WHERE dc.dealer_id = $1
      `;
      
      const countParams = [dealerId];
      let countParamIndex = 2;
      
      if (status && status !== 'all') {
        countQuery += ` AND dc.lead_status = $${countParamIndex}`;
        countParams.push(status);
        countParamIndex++;
      }

      if (handoffStatus && handoffStatus !== 'all') {
        if (handoffStatus === 'requested') {
          countQuery += ` AND dc.handoff_requested = true`;
        } else if (handoffStatus === 'pending') {
          countQuery += ` AND dc.handoff_requested = true`;
        } else if (handoffStatus === 'accepted') {
          countQuery += ` AND dc.handoff_requested = false`;
        }
      }

      const countResult = await pool.query(countQuery, countParams);

      const responseData = {
        success: true,
        data: {
          conversations: result.rows,
          pagination: {
            page: parseInt(page),
            limit: parseInt(limit),
            total: parseInt(countResult.rows[0].total),
            pages: Math.ceil(parseInt(countResult.rows[0].total) / parseInt(limit))
          }
        }
      };

      console.log('✅ Conversations retrieved successfully:', {
        count: result.rows.length,
        total: countResult.rows[0].total,
        page: page
      });

      return responseData;
      
    } catch (error) {
      console.error('❌ Error getting conversations:', error);
      return {
        success: false,
        error: error.message,
        data: {
          conversations: [],
          pagination: { page: 1, limit: 20, total: 0, pages: 0 }
        }
      };
    }
  }

  /**
   * Get analytics data for DAIVE analytics component
   */
  async getAnalytics(dealerId, startDate, endDate) {
    try {
      console.log('📊 Getting analytics for dealer:', dealerId, 'from', startDate, 'to', endDate);
      
      const { pool } = await import('../database/connection.js');
      
      // Get conversation statistics
      const conversationStats = await pool.query(`
        SELECT 
          DATE(created_at) as date,
          COUNT(*) as total_conversations,
          COUNT(CASE WHEN lead_status = 'qualified' THEN 1 END) as qualified_leads,
          COUNT(CASE WHEN handoff_requested = true THEN 1 END) as handoff_requests,
          AVG(lead_qualification_score) as avg_lead_score
        FROM daive_conversations 
        WHERE dealer_id = $1 
        AND created_at BETWEEN $2 AND $3
        GROUP BY DATE(created_at)
        ORDER BY date DESC
      `, [dealerId, startDate, endDate]);

      // Get total counts for the period
      const totalStats = await pool.query(`
        SELECT 
          COUNT(*) as total_conversations,
          COUNT(CASE WHEN lead_status = 'qualified' THEN 1 END) as total_qualified_leads,
          COUNT(CASE WHEN handoff_requested = true THEN 1 END) as total_handoff_requests,
          AVG(lead_qualification_score) as overall_avg_lead_score
        FROM daive_conversations 
        WHERE dealer_id = $1 
        AND created_at BETWEEN $2 AND $3
      `, [dealerId, startDate, endDate]);

      // Get message statistics
      const messageStats = await pool.query(`
        SELECT 
          DATE(cm.created_at) as date,
          COUNT(*) as total_messages,
          COUNT(CASE WHEN cm.role = 'user' THEN 1 END) as user_messages,
          COUNT(CASE WHEN cm.role = 'assistant' THEN 1 END) as ai_messages
        FROM conversation_messages cm
        JOIN daive_conversations dc ON cm.conversation_id = dc.id
        WHERE dc.dealer_id = $1 
        AND cm.created_at BETWEEN $2 AND $3
        GROUP BY DATE(cm.created_at)
        ORDER BY date DESC
      `, [dealerId, startDate, endDate]);

      const analytics = {
        daily: conversationStats.rows,
        totals: totalStats.rows[0] || {},
        messages: messageStats.rows,
        period: { startDate, endDate }
      };

      console.log('✅ Analytics retrieved successfully:', {
        dailyConversations: analytics.daily.length,
        totalConversations: analytics.totals.total_conversations,
        totalLeads: analytics.totals.total_qualified_leads
      });

      return analytics;
      
    } catch (error) {
      console.error('❌ Error getting analytics:', error);
      return {
        daily: [],
        totals: [],
        messages: [],
        period: { startDate, endDate },
        error: error.message
      };
    }
  }

