  getVehicleArrays(conversationContext) {
    // Initialize Daivesteps structure if it doesn't exist
    if (!conversationContext.Daivesteps) {
      conversationContext.Daivesteps = {};
    }
    
    const step3 = conversationContext.Daivesteps?.[3]?.slots || {};
    
    // ENHANCED: Check for inventory data in multiple locations
    const inventoryData = step3.inventoryData || conversationContext.inventoryData || [];
    
    return {
      sharedVehicles: step3.sharedVehicles || [],
      rejectedVehicles: step3.rejectedVehicles || [],
      selectedVehicles: step3.selectedVehicles || [],
      recentVehicleOptions: step3.recentVehicleOptions || [],
      inventoryData: inventoryData
    };
  }

