  /**
   * Update DAIVE structure with selected vehicle
   * This method is copied from DAIVEService to avoid cross-class method calls
   */
  updateDaiveStructureWithSelectedVehicle(conversationContext, selectedVehicle, selectionNumber) {
    // Initialize Daivesteps structure if it doesn't exist
    if (!conversationContext.Daivesteps) {
      conversationContext.Daivesteps = {};
    }
    
    if (!conversationContext.Daivesteps[3]) {
      conversationContext.Daivesteps[3] = { slots: {} };
    }
    
    if (!conversationContext.Daivesteps[3].slots) {
      conversationContext.Daivesteps[3].slots = {};
    }
    
    // Update VehicleSelection slot
    if (!conversationContext.Daivesteps[3].slots.VehicleSelection) {
      conversationContext.Daivesteps[3].slots.VehicleSelection = {};
    }
    
    conversationContext.Daivesteps[3].slots.VehicleSelection.selectedVehicle = selectedVehicle;
    conversationContext.Daivesteps[3].slots.VehicleSelection.selectionNumber = selectionNumber;
    conversationContext.Daivesteps[3].slots.VehicleSelection.hasSelectedVehicle = true;
    
    // ✅ FIX: Add vehicle to selectedVehicles array
    if (!conversationContext.Daivesteps[3].slots.selectedVehicles) {
      conversationContext.Daivesteps[3].slots.selectedVehicles = [];
    }
    
    // Add the selected vehicle to the array
    conversationContext.Daivesteps[3].slots.selectedVehicles.push({
      id: selectedVehicle.id,
      make: selectedVehicle.make,
      model: selectedVehicle.model,
      year: selectedVehicle.year,
      price: selectedVehicle.price,
      stockNumber: selectedVehicle.stock_number || 'unknown',
      vehicle_type: selectedVehicle.vehicle_type || selectedVehicle.body_style,
      selectionNumber: selectionNumber,
      selectedAt: new Date().toISOString(),
      features: selectedVehicle.features || []
    });
    
    console.log('✅ Vehicle added to selectedVehicles array:', {
      vehicle: `${selectedVehicle.year} ${selectedVehicle.make} ${selectedVehicle.model}`,
      arrayLength: conversationContext.Daivesteps[3].slots.selectedVehicles.length
    });
    
    // Update inventory_choice slot for compatibility
    conversationContext.Daivesteps[3].slots.inventory_choice = {
      id: selectedVehicle.id,
      make: selectedVehicle.make,
      model: selectedVehicle.model,
      year: selectedVehicle.year,
      price: selectedVehicle.price,
      stockNumber: selectedVehicle.stock_number || 'unknown',
      vehicle_type: selectedVehicle.vehicle_type || selectedVehicle.body_style,
      selectionNumber: selectionNumber,
      selectedAt: new Date().toISOString(),
      features: selectedVehicle.features || []
    };
    
    console.log(`🎯 DAIVE structure updated with selected vehicle: ${selectedVehicle.year} ${selectedVehicle.make} ${selectedVehicle.model}`);
  }

