  // Check if a message is a confirmation
  isConfirmationMessage(message) {
    const confirmationPatterns = [
      /^(yes|yeah|yep|yup|ok|okay|sure|absolutely|definitely|of course|go ahead|proceed|continue|let's do it|sounds good|perfect|great|excellent|wonderful|amazing|fantastic|love it|i like it|i want it|i'll take it|i'm interested|i'm ready|let's go|bring it on|count me in|i'm in|sign me up|let's move forward|let's proceed|i agree|i accept|i confirm|confirmed|deal|done|sold|i'll buy it|i'll take this one|this is the one|this works for me|i'm sold|i'm convinced)$/i
    ];
    
    return confirmationPatterns.some(pattern => pattern.test(message.trim()));
  }



  // Analyze confirmation context to determine what stage is being confirmed
  analyzeConfirmationContext(userMessage, conversationContext) {
    const previousMessages = conversationContext.messages || [];
    const lastAssistantMessage = previousMessages.filter(msg => msg.role === 'assistant').pop();
    const lastUserMessage = previousMessages.filter(msg => msg.role === 'user').pop();
    
    console.log(`🔍 Analyzing confirmation context:`);
    console.log(`   Current message: "${userMessage}"`);
    console.log(`   Last assistant message: "${lastAssistantMessage?.content || 'None'}"`);
    console.log(`   Last user message: "${lastUserMessage?.content || 'None'}"`);
    
    // Analyze the last assistant message to determine what was being asked
    const assistantContent = lastAssistantMessage?.content?.toLowerCase() || '';
    const userContent = userMessage.toLowerCase();
    
    // Define stage-specific confirmation patterns
    const stagePatterns = {
      'vehicle_selection': {
        patterns: [
          /proceed.*with.*this.*car/i,
          /select.*this.*vehicle/i,
          /choose.*this.*one/i,
          /go.*with.*this.*option/i,
          /this.*is.*the.*one/i,
          /would.*you.*like.*to.*proceed/i,
          /are.*you.*interested.*in.*this/i,
          /does.*this.*work.*for.*you/i,
          /is.*this.*what.*you.*are.*looking.*for/i,
          /would.*you.*like.*to.*see.*more/i,
          /shall.*we.*move.*forward/i,
          /ready.*to.*proceed/i
        ],
        nextAction: 'confirm_vehicle_selection',
        context: 'Customer confirming vehicle selection'
      },
      'test_drive': {
        patterns: [
          /schedule.*test.*drive/i,
          /bring.*the.*keys/i,
          /test.*drive.*this.*vehicle/i,
          /would.*you.*like.*to.*test.*drive/i,
          /ready.*for.*a.*test.*drive/i,
          /test.*drive.*scheduling/i,
          /when.*would.*you.*like.*to.*test.*drive/i,
          /test.*drive.*appointment/i
        ],
        nextAction: 'schedule_test_drive',
        context: 'Customer confirming test drive request'
      },
      'financing': {
        patterns: [
          /financing.*options/i,
          /payment.*plans/i,
          /monthly.*payment/i,
          /credit.*application/i,
          /loan.*terms/i,
          /interest.*rate/i,
          /down.*payment/i,
          /lease.*vs.*buy/i
        ],
        nextAction: 'proceed_with_financing',
        context: 'Customer confirming financing discussion'
      },
      'purchase': {
        patterns: [
          /purchase.*this.*vehicle/i,
          /buy.*this.*car/i,
          /finalize.*the.*deal/i,
          /complete.*the.*purchase/i,
          /ready.*to.*buy/i,
          /proceed.*with.*purchase/i,
          /sign.*the.*papers/i,
          /close.*the.*deal/i
        ],
        nextAction: 'proceed_with_purchase',
        context: 'Customer confirming purchase intent'
      }
    };
    
    // Check which stage the confirmation is for
    for (const [stage, config] of Object.entries(stagePatterns)) {
      const isStageConfirmation = config.patterns.some(pattern => 
        pattern.test(assistantContent) || pattern.test(userContent)
      );
      
      if (isStageConfirmation) {
        console.log(`✅ Confirmation detected for stage: ${stage}`);
        return {
          confirmedStage: stage,
          nextAction: config.nextAction,
          context: config.context,
          confidence: 0.9
        };
      }
    }
    
    // Default confirmation handling
    console.log(`⚠️ Generic confirmation detected`);
    return {
      confirmedStage: 'general',
      nextAction: 'proceed_with_general_confirmation',
      context: 'Customer providing general confirmation',
      confidence: 0.7
    };
  }

