  /**
   * Extract step completion data from conversation context
   */
  extractStepCompletion(conversationContext) {
    const stepCompleted = this.getStepCompletion(conversationContext) || {};
    return {
      inquiry: stepCompleted.inquiry || false,
      lead_capture: stepCompleted.lead_capture || false,
      vehicle_selection: stepCompleted.vehicle_selection || false,
      test_drive: stepCompleted.test_drive || false,
      trade_evaluation: stepCompleted.trade_evaluation || false,
      qualification: stepCompleted.qualification || false,
      purchase_commitment: stepCompleted.purchase_commitment || false,
      vehicle_preparation: stepCompleted.vehicle_preparation || false,
      finance_manager: stepCompleted.finance_manager || false,
      delivery: stepCompleted.delivery || false,
      csi_followup: stepCompleted.csi_followup || false
    };
  }

  // Note: extractVehicleArray method removed - use getVehicleArrays() helper method instead

  /**
   * Calculate lead qualification score
   */
  calculateLeadQualificationScore(conversationContext) {
    let score = 0;
    const stepCompleted = this.getStepCompletion(conversationContext) || {};
    
    // Base score for each completed step
    if (stepCompleted.inquiry) score += 10;
    if (stepCompleted.lead_capture) score += 15;
    if (stepCompleted.vehicle_selection) score += 20;
    if (stepCompleted.test_drive) score += 25;
    if (stepCompleted.qualification) score += 15;
    if (stepCompleted.purchase_commitment) score += 10;
    
    return Math.min(score, 100);
  }

  /**
   * Determine lead status based on conversation context
   */
  determineLeadStatus(conversationContext) {
    const stepCompleted = this.getStepCompletion(conversationContext) || {};
    
    if (stepCompleted.purchase_commitment) return 'hot';
    if (stepCompleted.test_drive) return 'warm';
    if (stepCompleted.vehicle_selection) return 'warm';
    if (stepCompleted.lead_capture) return 'warm';
    if (stepCompleted.inquiry) return 'cold';
    
    return 'cold';
  }

