  /**
   * Calculate conversation duration
   */
  calculateConversationDuration(conversationContext) {
    const created = conversationContext.created_at || conversationContext.createdAt;
    const updated = conversationContext.last_updated || conversationContext.lastUpdated;
    
    if (created && updated) {
      const start = new Date(created);
      const end = new Date(updated);
      return Math.floor((end - start) / 1000); // Duration in seconds
    }
    
    return 0;
  }

  /**
   * Calculate message count
   */
  calculateMessageCount(conversationContext) {
    const messages = conversationContext.messages || [];
    return messages.length;
  }

  /**
   * Save conversation context to database using the ConversationContextService
   * @param {Object} conversationContext - The conversation context to save
   * @returns {Promise<Object>} - The saved context data
   */
  async saveConversationContextToDatabase(conversationContext) {
    try {
      if (!this.conversationContextService) {
        console.warn('⚠️ ConversationContextService not initialized, skipping database save');
        console.log('🔍 Debug: conversationContextService is:', this.conversationContextService);
        console.log('🔍 Debug: typeof conversationContextService:', typeof this.conversationContextService);
        return null;
      }

      // Normalize current step to satisfy DB CHECK constraint valid_current_step
      const normalizeCurrentStep = (raw) => {
        if (!raw) return 'Inquiry';
        let key = String(raw)
          .toLowerCase()
          .replace(/[_-]/g, ' ')
          .replace(/^\s*step\s*\d+\s*/, '') // remove leading "step N"
          .replace(/^\s*\d+\s*/, '') // remove leading numbers
          .trim();

        // Canonical mapping to allowed labels
        const mapping = new Map([
          ['inquiry', 'Inquiry'],
          ['lead capture', 'Lead Capture'],
          ['lead', 'Lead Capture'],
          ['vehicle', 'Vehicle Selection'],
          ['vehicle selection', 'Vehicle Selection'],
          ['test drive', 'Test Drive'],
          ['trade evaluation', 'Trade Evaluation'],
          ['qualification', 'Qualification'],
          ['purchase commitment', 'Purchase Commitment'],
          ['vehicle prep', 'Vehicle Prep'],
          ['vehicle preparation', 'Vehicle Prep'],
          ['finance manager', 'Finance Manager'],
          ['delivery', 'Delivery'],
          ['csi & follow-ups', 'CSI & Follow-ups'],
          ['csi & followups', 'CSI & Follow-ups'],
          ['csi follow-ups', 'CSI & Follow-ups'],
          ['csi followup', 'CSI & Follow-ups'],
          ['csi follow ups', 'CSI & Follow-ups']
        ]);

        // Try direct match first
        if (mapping.has(key)) return mapping.get(key);

        // Heuristics: collapse multiple spaces and try again
        key = key.replace(/\s+/g, ' ');
        if (mapping.has(key)) return mapping.get(key);

        // Default to Inquiry if unknown
        return 'Inquiry';
      };

      const rawCurrentStep = conversationContext.Currentstep || conversationContext.currentStep || 'Inquiry';
      const safeCurrentStep = normalizeCurrentStep(rawCurrentStep);

      // Extract data from the optimized structure
      const contextData = {
        session_id: conversationContext.session_id || conversationContext.sessionId,
        user_id: conversationContext.user_id || conversationContext.userId || 'anonymous',
        dealer_id: conversationContext.dealer_id || conversationContext.dealerId,
        current_step: safeCurrentStep,
        daivesteps: conversationContext.Daivesteps || {},
        step_completion: this.extractStepCompletion(conversationContext),
        shared_vehicles: this.getVehicleArrays(conversationContext).sharedVehicles,
        rejected_vehicles: this.getVehicleArrays(conversationContext).rejectedVehicles,
        selected_vehicles: this.getVehicleArrays(conversationContext).selectedVehicles,
        lead_qualification_score: this.calculateLeadQualificationScore(conversationContext),
        lead_status: this.determineLeadStatus(conversationContext),
        customer_profile: this.extractCustomerProfile(conversationContext),
        budget_info: this.extractBudgetInfo(conversationContext),
        vehicle_preferences: this.extractVehiclePreferences(conversationContext),
        test_drive_info: this.extractTestDriveInfo(conversationContext),
        appointment_info: this.extractAppointmentInfo(conversationContext),
        finance_info: this.extractFinanceInfo(conversationContext),
        purchase_commitment: this.extractPurchaseCommitment(conversationContext),
        delivery_info: this.extractDeliveryInfo(conversationContext),
        csi_followup: this.extractCSIFollowup(conversationContext),
        conversation_duration: this.calculateConversationDuration(conversationContext),
        message_count: this.calculateMessageCount(conversationContext),
        handoff_requested: conversationContext.handoff_requested || false,
        handoff_to_user_id: conversationContext.handoff_to_user_id
      };

      const savedContext = await this.conversationContextService.upsertConversationContext(contextData);
      console.log('✅ Conversation context saved to database:', savedContext.session_id);
      return savedContext;
    } catch (error) {
      console.error('❌ Error saving conversation context to database:', error);
      // Don't throw error to avoid breaking the conversation flow
      return null;
    }
  }

 
