/**
 * ✅ NEW: Get top 5 features as a simple array to prevent nesting
 */
DAIVEService.prototype.getTopFeaturesAsArray = function(features) {
  if (!features) return [];
  
  // If it's already an array, return top 5
  if (Array.isArray(features)) {
    return features
      .filter(feature => feature && typeof feature === 'string' && feature.trim().length > 0)
      .slice(0, 5); // Limit to top 5 features
  }
  
  // If it's an object with a list property, extract that
  if (features.list && Array.isArray(features.list)) {
    return features.list
      .filter(feature => feature && typeof feature === 'string' && feature.trim().length > 0)
      .slice(0, 5);
  }
  
  // If it's a nested object, try to extract any array we can find
  if (typeof features === 'object') {
    // Look for any array property in the nested structure
    const findArrayInObject = (obj) => {
      if (Array.isArray(obj)) return obj;
      if (obj && typeof obj === 'object') {
        for (const key in obj) {
          if (Array.isArray(obj[key])) return obj[key];
          if (obj[key] && typeof obj[key] === 'object') {
            const nested = findArrayInObject(obj[key]);
            if (nested) return nested;
          }
        }
      }
      return [];
    };
    
    const extractedArray = findArrayInObject(features);
    return extractedArray
      .filter(feature => feature && typeof feature === 'string' && feature.trim().length > 0)
      .slice(0, 5);
  }
  
  // Fallback: return empty array
  return [];
};

